from pathlib import Path
import pandas as pd, json

def run_h022_validation(root='research_outputs/nvda_entry_discovery_agent_v2_validation'):
    out=Path(root); a=__import__('pcs.data.access',fromlist=['PCSDataAccess']).PCSDataAccess(); d=a.read_prices('NVDA','2022-01-01','2025-12-31').copy(); d.date=pd.to_datetime(d.date); d=d.sort_values('date'); q=a.read_prices('QQQ','2022-01-01','2025-12-31').copy(); q.date=pd.to_datetime(q.date); q=q.sort_values('date')
    prev=d.close.shift(); tr=pd.concat([d.high-d.low,(d.high-prev).abs(),(d.low-prev).abs()],axis=1).max(axis=1); d['sma200']=d.close.rolling(200,min_periods=200).mean(); d['volrel']=d.volume/d.volume.rolling(20,min_periods=20).mean(); d['ret5']=d.close.pct_change(5); q['sma50']=q.close.rolling(50,min_periods=50).mean()
    f=d.merge(q[['date','close','sma50']].rename(columns={'close':'qqq_close','sma50':'qqq_sma50'}),on='date',how='left'); f=f[f.date.between('2024-01-01','2025-12-31')]
    z=pd.read_parquet(out/'broad_pcs_outcome_map.parquet'); z.trade_date=pd.to_datetime(z.trade_date); z=z.merge(f[['date','close','sma200','volrel','ret5','qqq_close','qqq_sma50']],left_on='trade_date',right_on='date',how='left'); g=z[(z.close>z.sma200)&(z.qqq_close>z.qqq_sma50)&(z.volrel>1)&(z.ret5>0)&z.executable_pcs].sort_values('trade_date').copy(); g['gap']=g.trade_date.diff().dt.days.fillna(999); g['episode']=(g.gap>10).cumsum(); g=g.groupby('episode',as_index=False).head(1); neg=g.loc[g.realized_pnl<0,'realized_pnl'].sum(); pos=g.loc[g.realized_pnl>0,'realized_pnl'].sum(); result={'candidate_id':'V2_H022','status':'VALIDATION_COMPLETED','episodes':len(g),'trades':len(g),'pnl':float(g.realized_pnl.sum()),'expectancy':float(g.realized_pnl.mean()) if len(g) else None,'pf':float(pos/abs(neg)) if neg else None,'win_rate':float((g.realized_pnl>0).mean()) if len(g) else None,'stop_rate':float(g.stopped.mean()) if len(g) else None,'worst_trade':float(g.realized_pnl.min()) if len(g) else None,'years':sorted(g.trade_date.dt.year.unique().tolist()),'final_oos_read':False,'production_changes':False}; g.to_parquet(out/'v2_h022_validation_trades.parquet',index=False); (out/'v2_h022_validation_result.json').write_text(json.dumps(result,indent=2),encoding='utf-8'); return result
